output.query:
let lookback = 7d;
let etlTools = dynamic(["airbyte","fivetran","stitch","talend","meltano","singer-io","dbt","nifi","pentaho","kettle","informatica","matillion","rclone"]);
let proc = DeviceProcessEvents
| where Timestamp > ago(lookback)
| where FileName has_any (etlTools) or ProcessCommandLine has_any (etlTools) or ProcessCommandLine has_any ("aws lambda create-function","aws lambda invoke","aws lambda update-function-code","aws glue create-job","aws glue start-job-run","aws datapipeline")
| project Timestamp, Source="Endpoint", DeviceName, Account=AccountName, FileName, ProcessCommandLine, InitiatingProcessFileName, InitiatingProcessCommandLine;
let cloud = CloudAppEvents
| where Timestamp > ago(lookback)
| where ActionType has_any ("CreateFunction","UpdateFunctionCode","Invoke","CreateJob","StartJobRun","CreatePipeline","CreateDataFlow")
| project Timestamp, Source="CloudApp", DeviceName=tostring(IPAddress), Account=AccountDisplayName, FileName=Application, ProcessCommandLine=ActionType, InitiatingProcessFileName=UserAgent, InitiatingProcessCommandLine=ObjectName;
union proc, cloud
| order by Timestamp desc
